const $in = $input.first().json;

const h = $in.headers || {};
const ip = String(h['x-real-ip'] || String(h['x-forwarded-for'] || '').split(',')[0] || 'unknown').trim();
const store = $getWorkflowStaticData('global');
const now = Date.now();
store.hits = Object.fromEntries(Object.entries(store.hits || {}).map(([k, v]) => [k, v.filter(t => now - t < 3600e3)]).filter(([, v]) => v.length));
const mine = store.hits[ip] || [];
if (mine.length >= 3000) return [{ json: { ok: false, status: 429, body: { success: false, message: 'Too many attempts from this network. Please try again in an hour.' } } }];
const count = () => { store.hits[ip] = [...mine, now]; };

// Serve a fresh copy for 20 seconds so many parents refreshing at once don't each hit the database.
const cache = $getWorkflowStaticData('global');
const key = 'f:' + String(($in.query || {}).slug || '');
const hit = (cache.c || {})[key];
if (hit && Date.now() - hit.at < 20000) return [{ json: { ok: false, status: 200, body: hit.body } }];

const q = $in.query || {};
const slug = String(q.slug || '').toLowerCase();
if (!/^[a-z0-9-]{2,40}$/.test(slug)) return [{ json: { ok: false, status: 404, body: { success: false, message: 'This page does not exist.' } } }];
count();
// No login: the viewer is nobody, so only published fixtures are shown.
return [{ json: { ok: true, phone: '', code: slug, slug, _q: { slug } } }];

const $in = $input.first().json;
if (!$in.id) return [{ json: { ok: false, status: 404, body: { success: false, message: "Tournament not found." } } }];
return [{ json: { ok: true, ...$in } }];

const b2 = $('Authorize B2').isExecuted ? $('Authorize B2').first().json : {};
const dl = b2?.apiInfo?.storageApi?.downloadUrl;
const tokenOf = node => { try { return $(node).isExecuted ? $(node).first().json.authorizationToken : null; } catch { return null; } };
const signWith = (key, node) => { const t = tokenOf(node); return key && dl && t ? `${dl}/file/mypaltan-profile-photos/${key.split('/').map(encodeURIComponent).join('/')}?Authorization=${t}` : null; };
const parseJ = v => { if (v === null || v === undefined) return null; if (typeof v === 'object') return v; try { return JSON.parse(v); } catch { return null; } };
// ── Points tables (embedded in n8n Code nodes; also unit-tested in node) ──
// division: { points: {win, tie, no_result, loss, tiebreakers}, format }, sport: 'CRICKET' | 'FOOTBALL' | ...
// teams: [{ entry_id, group_no }], matches: [{ stage, group_no, status, home_entry_id, away_entry_id, winner_entry_id,
//   home_score, away_score, outcome, standing: [{batting, runs, balls}] }]
// Returns [{ group_no, rows: [...], complete }] with rows in finishing order.
function computeStandings(division, sport, teams, matches) {
  const pts = division.points || {};
  const P = { win: pts.win ?? 2, tie: pts.tie ?? 1, nr: pts.no_result ?? 1, loss: pts.loss ?? 0 };
  const breakers = Array.isArray(pts.tiebreakers) && pts.tiebreakers.length ? pts.tiebreakers : (sport === 'CRICKET' ? ['NRR', 'HEAD_TO_HEAD'] : ['GOAL_DIFF', 'GOALS_FOR', 'HEAD_TO_HEAD']);
  const groupMatches = matches.filter(m => m.stage === 'GROUP');
  const groupNos = [...new Set(teams.map(t => t.group_no || 1))].sort((a, b) => a - b);
  return groupNos.map(g => {
    const rows = new Map(teams.filter(t => (t.group_no || 1) === g).map(t => [t.entry_id, {
      entry_id: t.entry_id, played: 0, won: 0, lost: 0, tied: 0, no_result: 0, points: 0,
      runs_for: 0, balls_for: 0, runs_against: 0, balls_against: 0, nrr: 0, goals_for: 0, goals_against: 0, goal_diff: 0 }]));
    const inGroup = groupMatches.filter(m => (m.group_no || 1) === g);
    const results = []; // for head-to-head
    for (const m of inGroup) {
      if (m.status !== 'COMPLETED') continue;
      const h = rows.get(m.home_entry_id), a = rows.get(m.away_entry_id);
      if (!h || !a) continue;
      h.played++; a.played++;
      const outcome = m.outcome || (m.winner_entry_id ? 'WIN' : (m.home_score != null && m.home_score === m.away_score ? 'TIE' : 'NO_RESULT'));
      if (outcome === 'WIN' && m.winner_entry_id) {
        const w = rows.get(m.winner_entry_id), l = w === h ? a : h;
        if (w) { w.won++; w.points += P.win; l.lost++; l.points += P.loss; results.push([w.entry_id, l.entry_id]); }
      } else if (outcome === 'TIE') {
        h.tied++; a.tied++; h.points += P.tie; a.points += P.tie;
      } else {
        h.no_result++; a.no_result++; h.points += P.nr; a.points += P.nr;
      }
      if (sport === 'CRICKET' && outcome !== 'NO_RESULT') {
        // Net run rate uses runs and overs from both innings; abandoned matches are left out.
        for (const inn of m.standing || []) {
          const bat = rows.get(inn.batting), bowl = bat === h ? a : h;
          if (!bat) continue;
          bat.runs_for += inn.runs; bat.balls_for += inn.balls;
          bowl.runs_against += inn.runs; bowl.balls_against += inn.balls;
        }
      } else if (sport !== 'CRICKET' && m.home_score != null && m.away_score != null) {
        h.goals_for += m.home_score; h.goals_against += m.away_score;
        a.goals_for += m.away_score; a.goals_against += m.home_score;
      }
    }
    for (const r of rows.values()) {
      const rate = (runs, balls) => balls > 0 ? runs * 6 / balls : 0;
      r.nrr = Math.round((rate(r.runs_for, r.balls_for) - rate(r.runs_against, r.balls_against)) * 1000) / 1000;
      r.goal_diff = r.goals_for - r.goals_against;
    }
    const beat = (x, y) => results.some(([w, l]) => w === x && l === y);
    const key = {
      NRR: r => r.nrr, WINS: r => r.won, GOAL_DIFF: r => r.goal_diff, GOALS_FOR: r => r.goals_for,
      GAMES_DIFF: r => r.goal_diff, POINT_DIFF: r => r.goal_diff,
    };
    const sorted = [...rows.values()].sort((x, y) => {
      if (y.points !== x.points) return y.points - x.points;
      for (const b of breakers) {
        if (b === 'HEAD_TO_HEAD') {
          if (beat(x.entry_id, y.entry_id) && !beat(y.entry_id, x.entry_id)) return -1;
          if (beat(y.entry_id, x.entry_id) && !beat(x.entry_id, y.entry_id)) return 1;
          continue;
        }
        const f = key[b];
        if (f && f(y) !== f(x)) return f(y) - f(x);
      }
      return 0;
    });
    sorted.forEach((r, i) => { r.position = i + 1; });
    const complete = inGroup.length > 0 && inGroup.every(m => m.status === 'COMPLETED');
    return { group_no: g, rows: sorted, complete };
  });
}

/** When every group match is done: { 'G1#1': entryId, ... } for the knockout places. */
function qualifiers(groups) {
  const out = {};
  if (!groups.length || !groups.every(g => g.complete)) return out;
  for (const g of groups) g.rows.forEach(r => { out[`G${g.group_no}#${r.position}`] = r.entry_id; });
  return out;
}


const t = $('Check Found').first().json;
const owner = Number(t.is_owner) === 1, published = !!t.published_at;
const G = 'ABCDEFGHIJKLMNOP';
const divisions = (parseJ(t.divisions) || []).sort((a, b) => a.sort_order - b.sort_order);
const teams = (parseJ(t.teams) || []).map(e => ({ entry_id: e.entry_id, division_id: e.division_id, group_no: e.group_no, seed: e.seed, team_code: e.team_code,
  name: e.team_name, short: e.team_short, logo_url: signWith(e.logo_key, 'Team Link') }));
const show = owner || published;
const matches = show ? (parseJ(t.matches) || []) : [];
const out = divisions.map(d => {
  const dm = matches.filter(m => m.division_id === d.id).sort((a, b) => a.match_no - b.match_no);
  const groups = Math.max(1, ...dm.filter(m => m.group_no).map(m => m.group_no));
  const refLabel = ref => { if (!ref) return null; let m = /^G(\d+)#(\d+)$/.exec(ref);
    if (m) { const pos = ['', '1st', '2nd', '3rd', '4th', '5th', '6th', '7th', '8th'][+m[2]] || `${m[2]}th`; return groups > 1 ? `${pos} Group ${G[+m[1] - 1]}` : pos; }
    m = /^W#(\d+)$/.exec(ref); if (m) { const src = dm.find(x => x.match_no === +m[1]); return `Winner ${src?.label || 'M' + m[1]}`; } return ref; };
  return { id: d.id, name: d.name, format: d.format, group_count: d.group_count, qualify_per_group: d.qualify_per_group, match_rules: parseJ(d.match_rules) || {},
    settings: owner ? { start: d.fixture_start, pitches: d.fixture_pitches, gap_minutes: d.fixture_gap_minutes, draw: d.fixture_draw } : undefined,
    teams: teams.filter(e => e.division_id === d.id),
    matches: dm.map(m => ({ id: m.id, match_no: m.match_no, stage: m.stage, group_no: m.group_no, round_no: m.round_no, label: m.label,
      home_entry_id: m.home_entry_id, away_entry_id: m.away_entry_id, home_label: refLabel(m.home_ref), away_label: refLabel(m.away_ref),
      pitch: m.pitch, scheduled_at: m.scheduled_at, status: m.status, home_score: m.home_score, away_score: m.away_score,
      result_text: m.result_text || null, winner_entry_id: m.winner_entry_id || null, summary: parseJ(m.summary) || null })),
    // Points table per group, once the division has group matches.
    standings: dm.some(m => m.stage === 'GROUP')
      ? computeStandings({ points: parseJ(d.points) || {} }, t.sport, teams.filter(e => e.division_id === d.id),
          dm.map(m => ({ ...m, outcome: m.outcome && m.outcome !== 'null' ? m.outcome : null, standing: parseJ(m.standing) || [] })))
      : [] };
});
// The organiser is warned when confirmed teams changed after the fixtures were made.
const scheduled = new Set(matches.flatMap(m => [m.home_entry_id, m.away_entry_id]).filter(Boolean));
const teamsChanged = owner && matches.length > 0 && out.some(d => d.matches.length && d.format !== 'KNOCKOUT' && d.teams.some(e => !scheduled.has(e.entry_id)));
return [{ json: { status: 200, body: { success: true, sport: t.sport, code: t.code, name: t.name, status: t.status, is_owner: owner, published, published_at: t.published_at,
  start_date: t.start_date, end_date: t.end_date, day_start: t.day_start, day_end: t.day_end, divisions: out, my_entry_ids: parseJ(t.my_entries) || [], teams_changed: teamsChanged } } }];

const out = JSON.parse(JSON.stringify($input.first().json));

// Children's names on public pages: first name + last initial ("Aarav Shah" → "Aarav S.").
const short = n => { const w = String(n || '').trim().split(/\s+/).filter(Boolean); return w.length < 2 ? (w[0] || '') : `${w[0]} ${w[w.length - 1][0].toUpperCase()}.`; };
if (out.status === 200 && out.body && out.body.success) {
  // The match endpoint wraps its data in body.match.
  const b = out.body.match || out.body;
  for (const k of ['is_owner', 'my_entry_ids', 'teams_changed']) delete b[k];
  for (const d of b.divisions || []) delete d.settings;
}

const cache = $getWorkflowStaticData('global');
const now = Date.now();
cache.c = Object.fromEntries(Object.entries(cache.c || {}).filter(([, v]) => now - v.at < 60000));
if (out.status === 200 && out.body && out.body.success) cache.c['f:' + String(($('Check Login').first().json._q || {}).slug || '')] = { at: now, body: out.body };
return [{ json: out }];
